type View = "Panou" | "Mișcări" | "Plan săptămânal" | "Datorii" | "Economii" | "Bonuri" | "Asistent" | "Sincronizare" | "Setări";

const STORE_KEY = "buget-familie:app-data-v3";
const money = new Intl.NumberFormat("ro-RO", { style: "currency", currency: "RON", maximumFractionDigits: 0 });
const exactMoney = new Intl.NumberFormat("ro-RO", { style: "currency", currency: "RON", minimumFractionDigits: 2, maximumFractionDigits: 2 });
const navigation: { label: Exclude<View, "Setări">; icon: typeof LayoutDashboard }[] = [
  { label: "Panou", icon: LayoutDashboard },
  { label: "Mișcări", icon: WalletCards },
  { label: "Plan săptămânal", icon: Goal },
  { label: "Datorii", icon: CircleDollarSign },
  { label: "Economii", icon: PiggyBank },
  { label: "Bonuri", icon: ReceiptText },
  { label: "Asistent", icon: Bot },
  { label: "Sincronizare", icon: Cloud },
];

const newId = (prefix: string) => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
const todayLabel = () => new Intl.DateTimeFormat("ro-RO", { day: "2-digit", month: "short" }).format(new Date());
const readNumber = (value: string) => Number(value.replace(",", "."));

function BudgetRibbon({ spent, budget, color = "#143C36" }: { spent: number; budget: number; color?: string }) {
  const percentage = budget > 0 ? Math.min(100, (spent / budget) * 100) : 0;
  return <div className="ribbon-track" aria-label={`${Math.round(percentage)}% utilizat`}><div className="ribbon-fill" style={{ width: `${percentage}%`, backgroundColor: color }} /><span className="ribbon-notch" style={{ left: "25%" }} /><span className="ribbon-notch" style={{ left: "50%" }} /><span className="ribbon-notch" style={{ left: "75%" }} /></div>;
}

function Metric({ label, value, detail, tone = "forest", icon: Icon }: { label: string; value: string; detail: string; tone?: "forest" | "coral" | "honey"; icon: typeof WalletCards }) {
  const tones = { forest: "bg-[#E4EEE9] text-[#143C36]", coral: "bg-[#F9E4DE] text-[#A74B37]", honey: "bg-[#FBF0D2] text-[#8B6214]" };
  return <section className="paper-card metric-card"><div className={cn("metric-icon", tones[tone])}><Icon size={18} strokeWidth={2.2} /></div><p className="eyebrow">{label}</p><p className="metric-value">{value}</p><p className="metric-delta">{detail}</p></section>;
}

function EmptyState({ icon: Icon, title, copy, action }: { icon: typeof PiggyBank; title: string; copy: string; action?: ReactElement }) {
  return <section className="paper-card empty-state"><div className="empty-icon"><Icon size={23} /></div><h2>{title}</h2><p>{copy}</p>{action && <div className="empty-action">{action}</div>}</section>;
}

function TransactionDialog({ trigger, transaction, memberName, onSave }: { trigger: ReactElement; transaction?: Transaction; memberName: string; onSave: (item: Transaction) => void }) {
  const [open, setOpen] = useState(false); const familyConfig = useMemo(() => { try { return JSON.parse(window.localStorage.getItem(STORE_KEY) || "{}").settings; } catch { return undefined; } }, [open]);
  const members = familyConfig?.members?.length ? familyConfig.members : [{ id: "member-me", name: memberName || "Eu" }]; const sources = familyConfig?.paymentSources?.length ? familyConfig.paymentSources : [{ id: "source-card", name: "Card debit", kind: "card" }]; const categories = Array.from(new Set([...expenseCategories, ...(familyConfig?.customCategories || [])]));
  const [kind, setKind] = useState<TransactionKind>(transaction?.kind ?? "expense"); const [title, setTitle] = useState(transaction?.title ?? ""); const [amount, setAmount] = useState(transaction ? String(transaction.amount) : ""); const [category, setCategory] = useState(transaction?.category ?? "Alimente"); const [source, setSource] = useState(transaction?.source ?? "Card debit"); const [person, setPerson] = useState(transaction?.person ?? (memberName || "Eu")); const [note, setNote] = useState(transaction?.note ?? "");
  useEffect(() => { if (open) { setKind(transaction?.kind ?? "expense"); setTitle(transaction?.title ?? ""); setAmount(transaction ? String(transaction.amount) : ""); setCategory(transaction?.category ?? "Alimente"); setSource(transaction?.source ?? (sources[0]?.name || "Card debit")); setPerson(transaction?.person ?? (members[0]?.name || memberName || "Eu")); setNote(transaction?.note ?? ""); } }, [open, transaction, memberName, members, sources]);
  const submit = () => { const numeric = readNumber(amount); if (!title.trim() || !Number.isFinite(numeric) || numeric <= 0) return; onSave({ id: transaction?.id ?? newId("tx"), title: title.trim(), amount: numeric, kind, category: kind === "income" ? "Venit" : category, source, person, date: transaction?.date || todayLabel(), note: note.trim() || undefined }); setOpen(false); };
  return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild>{trigger}</DialogTrigger><DialogContent className="add-dialog"><DialogHeader><DialogTitle>{transaction ? "Modifică mișcarea" : "Înregistrează o mișcare"}</DialogTitle></DialogHeader><div className="kind-switch"><button onClick={() => setKind("expense")} className={cn(kind === "expense" && "is-active")}>Cheltuială</button><button onClick={() => setKind("income")} className={cn(kind === "income" && "is-active income")}>Venit</button></div><label className="field-label">Denumire<Input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="ex. Cumpărături la magazin" autoFocus /></label><div className="dialog-grid"><label className="field-label">Sumă (lei)<Input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" placeholder="0,00" /></label><label className="field-label">Plătit de<select value={person} onChange={(event) => setPerson(event.target.value)}>{members.map((member: { id: string; name: string }) => <option key={member.id} value={member.name}>{member.name}</option>)}</select></label></div><div className="dialog-grid"><label className="field-label">Din sursa<select value={source} onChange={(event) => setSource(event.target.value)}>{sources.map((item: { id: string; name: string }) => <option key={item.id} value={item.name}>{item.name}</option>)}</select></label>{kind === "expense" && <label className="field-label">Categorie<select value={category} onChange={(event) => setCategory(event.target.value)}>{categories.map((item) => <option key={item}>{item}</option>)}</select></label>}</div><label className="field-label">Notiță opțională<Textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="Detalii utile pentru familie" /></label><Button onClick={submit} className="save-transaction"><Check size={16} /> {transaction ? "Salvează modificarea" : "Salvează mișcarea"}</Button></DialogContent></Dialog>;
}

function DebtDialog({ trigger, debt, onSave }: { trigger: ReactElement; debt?: Debt; onSave: (item: Debt) => void }) {
  const [open, setOpen] = useState(false); const [name, setName] = useState(debt?.name ?? ""); const [remaining, setRemaining] = useState(debt ? String(debt.remaining) : ""); const [monthly, setMonthly] = useState(debt ? String(debt.monthly) : ""); const [due, setDue] = useState(debt?.due ?? "");
  useEffect(() => { if (open) { setName(debt?.name ?? ""); setRemaining(debt ? String(debt.remaining) : ""); setMonthly(debt ? String(debt.monthly) : ""); setDue(debt?.due ?? ""); } }, [open, debt]);
  const submit = () => { const remainingValue = readNumber(remaining); const monthlyValue = readNumber(monthly); if (!name.trim() || !Number.isFinite(remainingValue) || remainingValue < 0 || !Number.isFinite(monthlyValue) || monthlyValue < 0) return; onSave({ id: debt?.id ?? newId("debt"), name: name.trim(), remaining: remainingValue, monthly: monthlyValue, due: due.trim() || "Nespecificat", tone: debt?.tone ?? "forest" }); setOpen(false); };
  return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild>{trigger}</DialogTrigger><DialogContent className="add-dialog"><DialogHeader><DialogTitle>{debt ? "Modifică datoria" : "Adaugă datorie"}</DialogTitle></DialogHeader><label className="field-label">Denumire<Input value={name} onChange={(event) => setName(event.target.value)} placeholder="ex. Credit bancar" autoFocus /></label><div className="dialog-grid"><label className="field-label">Sold rămas (lei)<Input value={remaining} onChange={(event) => setRemaining(event.target.value)} inputMode="decimal" /></label><label className="field-label">Rată lunară (lei)<Input value={monthly} onChange={(event) => setMonthly(event.target.value)} inputMode="decimal" /></label></div><label className="field-label">Scadență / zi de plată<Input value={due} onChange={(event) => setDue(event.target.value)} placeholder="ex. 5 septembrie" /></label><Button onClick={submit} className="save-transaction"><Check size={16} /> Salvează datoria</Button></DialogContent></Dialog>;
}

function SavingsDialog({ trigger, goal, onSave }: { trigger: ReactElement; goal?: SavingsGoal; onSave: (item: SavingsGoal) => void }) {
  const [open, setOpen] = useState(false); const [name, setName] = useState(goal?.name ?? ""); const [current, setCurrent] = useState(goal ? String(goal.current) : ""); const [target, setTarget] = useState(goal ? String(goal.target) : ""); const [due, setDue] = useState(goal?.due ?? "");
  useEffect(() => { if (open) { setName(goal?.name ?? ""); setCurrent(goal ? String(goal.current) : ""); setTarget(goal ? String(goal.target) : ""); setDue(goal?.due ?? ""); } }, [open, goal]);
  const submit = () => { const currentValue = readNumber(current); const targetValue = readNumber(target); if (!name.trim() || !Number.isFinite(currentValue) || currentValue < 0 || !Number.isFinite(targetValue) || targetValue <= 0) return; onSave({ id: goal?.id ?? newId("goal"), name: name.trim(), current: currentValue, target: targetValue, due: due.trim() || "Fără termen", tone: goal?.tone ?? "honey" }); setOpen(false); };
  return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild>{trigger}</DialogTrigger><DialogContent className="add-dialog"><DialogHeader><DialogTitle>{goal ? "Modifică obiectivul" : "Obiectiv de economisire"}</DialogTitle></DialogHeader><label className="field-label">Pentru ce economisiți?<Input value={name} onChange={(event) => setName(event.target.value)} placeholder="ex. Fond de siguranță" autoFocus /></label><div className="dialog-grid"><label className="field-label">Strâns până acum (lei)<Input value={current} onChange={(event) => setCurrent(event.target.value)} inputMode="decimal" /></label><label className="field-label">Țintă (lei)<Input value={target} onChange={(event) => setTarget(event.target.value)} inputMode="decimal" /></label></div><label className="field-label">Termen<Input value={due} onChange={(event) => setDue(event.target.value)} placeholder="ex. decembrie 2026" /></label><Button onClick={submit} className="save-transaction"><Check size={16} /> Salvează obiectivul</Button></DialogContent></Dialog>;
}

function localInsight(data: AppData, question = "") {
  const income = data.transactions.filter((item) => item.kind === "income").reduce((sum, item) => sum + item.amount, 0);
  const expenses = data.transactions.filter((item) => item.kind === "expense").reduce((sum, item) => sum + item.amount, 0);
  const monthlyDebt = data.debts.reduce((sum, item) => sum + item.monthly, 0);
  const plan = data.settings.salaryPlan; const allocated = plan.allocations.reduce((sum, item) => sum + item.amount, 0); const planLeft = plan.totalLimit - allocated; const payDate = plan.nextPayday ? new Date(`${plan.nextPayday}T12:00:00`) : undefined; const daysLeft = payDate && !Number.isNaN(payDate.valueOf()) ? Math.max(1, Math.ceil((payDate.valueOf() - Date.now()) / 86_400_000)) : undefined;
  const groups = Object.entries(data.transactions.filter((item) => item.kind === "expense").reduce<Record<string, number>>((result, item) => ({ ...result, [item.category]: (result[item.category] || 0) + item.amount }), {})).sort((a, b) => b[1] - a[1]);
  const largestDebt = [...data.debts].sort((a, b) => b.remaining - a.remaining)[0];
  const mostBehind = [...data.savings].sort((a, b) => (b.target - b.current) - (a.target - a.current))[0];
  const normalized = question.toLowerCase();
  if (normalized.includes("buget") || normalized.includes("limit") || normalized.includes("săptăm") || normalized.includes("saptam")) return plan.totalLimit ? `Planul până la salariu este ${money.format(plan.totalLimit)}; ai alocat ${money.format(allocated)} și mai sunt ${money.format(planLeft)} nealocați. ${daysLeft ? `Sunt ${daysLeft} zile până la data următorului salariu.` : "Adaugă data următorului salariu pentru calculul zilelor rămase."}` : "Nu ai stabilit încă o limită până la următorul salariu. Deschide Plan săptămânal, introdu suma totală și data următorului venit.";
  if (!data.transactions.length && !data.debts.length && !data.savings.length) return "Nu ai încă date suficiente pentru analiză. Înregistrează prima mișcare, datorie sau economie; fiecare modul se va actualiza după aceea.";
  if (normalized.includes("cheltu") || normalized.includes("categorie") || normalized.includes("mult")) return groups[0] ? `Cea mai mare categorie de cheltuieli este ${groups[0][0]}, cu ${money.format(groups[0][1])}. ${groups[1] ? `Următoarea este ${groups[1][0]}, cu ${money.format(groups[1][1])}.` : ""}` : "Nu există încă cheltuieli categorisite.";
  if (normalized.includes("dator") || normalized.includes("rat")) return largestDebt ? `Cea mai mare datorie înregistrată este ${largestDebt.name}, cu sold de ${money.format(largestDebt.remaining)} și rată lunară de ${money.format(largestDebt.monthly)}. Scadența notată este ${largestDebt.due}.` : "Nu există datorii înregistrate.";
  if (normalized.includes("econom") || normalized.includes("obiectiv")) return mostBehind ? `Obiectivul cu suma cea mai mare rămasă este ${mostBehind.name}: mai trebuie ${money.format(Math.max(0, mostBehind.target - mostBehind.current))} până la ținta de ${money.format(mostBehind.target)}.` : "Nu există obiective de economisire înregistrate.";
  if (normalized.includes("dispon") || normalized.includes("sold") || normalized.includes("plan")) return `Ai ${money.format(income)} venituri, ${money.format(expenses)} cheltuieli și ${money.format(monthlyDebt)} rate lunare planificate. Diferența după rate este ${money.format(income - expenses - monthlyDebt)}.`;
  return `Înregistrările locale arată ${money.format(income)} venituri și ${money.format(expenses)} cheltuieli. ${groups[0] ? `Cea mai mare categorie este ${groups[0][0]}. ` : ""}${monthlyDebt ? `Ratele lunare planificate sunt ${money.format(monthlyDebt)}. ` : ""}${plan.totalLimit ? `Planul are ${money.format(planLeft)} încă nealocați.` : ""}`;
}

function AssistantCard({ data, presetQuestion }: { data: AppData; presetQuestion?: string }) {
  const [question, setQuestion] = useState(""); const [response, setResponse] = useState(() => localInsight(data));
  useEffect(() => { setResponse(localInsight(data)); }, [data]);
  useEffect(() => { if (presetQuestion) setResponse(localInsight(data, presetQuestion)); }, [data, presetQuestion]);
  const answer = () => { if (!question.trim()) return; setResponse(localInsight(data, question)); setQuestion(""); };
  return <section className="assistant-card"><div className="assistant-orbit"><Sparkles size={17} /></div><div><p className="eyebrow text-[#DDEAE4]">ANALIZĂ EXPLICABILĂ</p><h2>O privire calmă înainte de următoarea decizie.</h2></div><p className="assistant-response">{response}</p><div className="assistant-input"><input value={question} onChange={(event) => setQuestion(event.target.value)} onKeyDown={(event) => event.key === "Enter" && answer()} placeholder="ex. Care e cea mai mare cheltuială?" /><button aria-label="Analizează întrebarea" onClick={answer}><Send size={16} /></button></div><p className="assistant-disclaimer">Răspunsul folosește numai înregistrările locale, planul, datoriile și obiectivele afișate în aplicație. Nu este consultanță financiară sau de investiții.</p></section>;
}

function Dashboard({ data, onAdd, onGo }: { data: AppData; onAdd: (transaction: Transaction) => void; onGo: (view: View) => void }) {
  const income = useMemo(() => data.transactions.filter((item) => item.kind === "income").reduce((sum, item) => sum + item.amount, 0), [data.transactions]);
  const expenses = useMemo(() => data.transactions.filter((item) => item.kind === "expense").reduce((sum, item) => sum + item.amount, 0), [data.transactions]);
  const plannedDebt = useMemo(() => data.debts.reduce((sum, item) => sum + item.monthly, 0), [data.debts]);
  const available = income - expenses - plannedDebt;
  const savings = useMemo(() => data.savings.reduce((sum, item) => sum + item.current, 0), [data.savings]);
  const categories = useMemo(() => Object.entries(data.transactions.filter((item) => item.kind === "expense").reduce<Record<string, number>>((result, item) => ({ ...result, [item.category]: (result[item.category] || 0) + item.amount }), {})).map(([label, spent]) => ({ label, spent, color: categoryColors[label] || "#7C857F" })).slice(0, 4), [data.transactions]);
  const chartData = useMemo(() => data.transactions.filter((item) => item.kind === "expense").slice(0, 7).reverse().map((item, index) => ({ day: index === 0 ? "Acum" : item.date.slice(0, 5), amount: item.amount })), [data.transactions]);
  const empty = !data.transactions.length && !data.debts.length && !data.savings.length && !data.receipts.length;
  if (empty) return <section className="onboarding-page"><header className="view-header"><div><p className="eyebrow">SPAȚIU NOU · FIȘA 01</p><h1>Pune prima cifră <em>la locul ei.</em></h1><p className="header-subtitle">Datele tale încep goale. Adaugă doar ce este real pentru familia voastră.</p></div><TransactionDialog memberName={data.settings.memberName} onSave={onAdd} trigger={<Button className="quick-add"><Plus size={17} /> Prima mișcare</Button>} /></header><div className="onboarding-workbench"><div className="onboarding-center"><div className="onboarding-grid"><EmptyState icon={WalletCards} title="Înregistrează un venit sau o cheltuială" copy="Începe cu salariul, o factură sau o cheltuială de azi. Poți modifica sau șterge orice intrare ulterior." action={<TransactionDialog memberName={data.settings.memberName} onSave={onAdd} trigger={<Button className="outline-action"><Plus size={16} /> Adaugă mișcare</Button>} />} /><EmptyState icon={PiggyBank} title="Setează un obiectiv" copy="Economiile devin vizibile atunci când au un nume, o țintă și un termen." action={<Button className="outline-action" onClick={() => onGo("Economii")}>Creează obiectiv <ChevronRight size={16} /></Button>} /><EmptyState icon={Settings} title="Configurează familia" copy="Adaugă membrii, cardurile, cash-ul și categoriile pe care le folosiți în realitate." action={<Button className="outline-action" onClick={() => onGo("Setări")}>Deschide setările <ChevronRight size={16} /></Button>} /></div><div className="onboarding-instrument"><span className="instrument-label">MĂSURĂ DE PORNIRE</span><BudgetRibbon spent={1} budget={3} color="#E6B84A" /><span><b>1 din 3</b> fișe recomandate pentru o primă imagine financiară.</span></div><p className="onboarding-note">Datele rămân locale până când alegi sincronizarea criptată sau un export manual.</p></div><aside className="onboarding-side"><section className="onboarding-context"><div className="assistant-orbit"><Sparkles size={17} /></div><p className="eyebrow text-[#DDEAE4]">ATELIERUL DE AZI</p><h2>Trei pași. O situație mai clară.</h2><p>Nu trebuie să introduci totul din prima zi. Începe cu ce contează acum.</p><div className="context-step"><span className="context-number honey">01</span><span>Înregistrează primul flux de bani</span></div><div className="context-step"><span className="context-number coral">02</span><span>Notează prima obligație sau economie</span></div><button onClick={() => onGo("Datorii")}>Deschide datoriile <ChevronRight size={15} /></button></section><section className="onboarding-code paper-card"><p className="eyebrow">ETICHETĂ DE FAMILIE</p><strong>{data.settings.familyCode}</strong><span>Cod local de identificare. Pentru sincronizare ai nevoie de parola de criptare a familiei.</span><button onClick={() => onGo("Sincronizare")}>Deschide sincronizarea <ChevronRight size={15} /></button></section></aside></div></section>;
  return <><header className="view-header"><div><p className="eyebrow">SITUAȚIA CURENTĂ</p><h1>Bună dimineața, <em>{data.settings.familyName}.</em></h1><p className="header-subtitle">Imaginea de ansamblu se actualizează pe măsură ce înregistrezi date reale.</p></div><div className="header-actions"><button className="icon-button settings-button" onClick={() => onGo("Setări")} aria-label="Setări"><Settings size={18} /></button><TransactionDialog memberName={data.settings.memberName} onSave={onAdd} trigger={<Button className="quick-add"><Plus size={17} /> Adaugă mișcare</Button>} /></div></header><div className="metrics-grid"><Metric label="Disponibil după rate" value={money.format(available)} detail="Venituri − cheltuieli − rate" icon={WalletCards} /><Metric label="Venituri" value={money.format(income)} detail={`${data.transactions.filter((item) => item.kind === "income").length} intrări` } tone="honey" icon={ArrowDownRight} /><Metric label="Cheltuit" value={money.format(expenses)} detail={`${data.transactions.filter((item) => item.kind === "expense").length} intrări`} tone="coral" icon={ArrowUpRight} /><Metric label="Economii alocate" value={money.format(savings)} detail={`${data.savings.length} obiective active`} icon={PiggyBank} /></div><div className="dashboard-columns"><div className="dashboard-main"><section className="paper-card spending-card"><div className="section-heading"><div><p className="eyebrow">RITMUL RECENT</p><h2>Cheltuieli înregistrate</h2></div><span className="period-chip">datele tale</span></div>{chartData.length ? <div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartData} margin={{ top: 10, right: 4, left: -20, bottom: 0 }}><defs><linearGradient id="spendingArea" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#143C36" stopOpacity={0.22} /><stop offset="100%" stopColor="#143C36" stopOpacity={0.01} /></linearGradient></defs><CartesianGrid vertical={false} stroke="#E8E3D8" strokeDasharray="2 5" /><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fill: "#758078", fontSize: 12, fontWeight: 700 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#9A9E96", fontSize: 11 }} /><Tooltip formatter={(value: number) => [exactMoney.format(value), "Cheltuit"]} /><Area dataKey="amount" type="monotone" stroke="#143C36" strokeWidth={3} fill="url(#spendingArea)" /></AreaChart></ResponsiveContainer></div> : <div className="chart-empty">Nu există încă cheltuieli pentru grafic.</div>}<div className="chart-insight"><Sparkles size={16} /><span>Graficul folosește numai cheltuielile introduse de voi.</span><button onClick={() => onGo("Mișcări")}>Registru <ChevronRight size={15} /></button></div></section><section className="paper-card budget-card"><div className="section-heading"><div><p className="eyebrow">CATEGORII FOLOSITE</p><h2>Unde au mers banii</h2></div><button className="text-button" onClick={() => onGo("Mișcări")}>Gestionează</button></div>{categories.length ? <div className="budget-list">{categories.map((item) => <div className="budget-row" key={item.label}><div className="budget-label"><span className="category-dot" style={{ backgroundColor: item.color }} /><strong>{item.label}</strong></div><div className="budget-ribbon"><BudgetRibbon spent={item.spent} budget={Math.max(item.spent, expenses)} color={item.color} /><span>{money.format(item.spent)}</span></div></div>)}</div> : <p className="empty-copy">Introdu prima cheltuială pentru a vedea categoriile.</p>}</section></div><aside className="dashboard-side"><section className="cashflow-card"><div className="cashflow-grid" /><p className="eyebrow text-[#DDEAE4]">RĂMAS DUPĂ CHELTUIELI ȘI RATE</p><p className="cashflow-value">{money.format(available).replace("RON", "")} <small>lei</small></p><p>Calcul local: venituri minus cheltuieli înregistrate și rate lunare planificate.</p><div className="cashflow-footer"><span><span className="live-dot" /> Date locale</span><button onClick={() => onGo("Setări")}>Transfer date <ChevronRight size={14} /></button></div></section><AssistantCard data={data} /></aside></div><section className="paper-card transactions-card"><div className="section-heading"><div><p className="eyebrow">ULTIMELE MIȘCĂRI</p><h2>Ce s-a întâmplat recent</h2></div><button className="text-button" onClick={() => onGo("Mișcări")}>Toate mișcările <ChevronRight size={15} /></button></div><div className="transaction-list">{data.transactions.slice(0, 5).map((item) => <div className="transaction-row" key={item.id}><div className={cn("transaction-icon", item.kind === "income" ? "income" : "expense")}>{item.kind === "income" ? <ArrowDownRight size={17} /> : <ReceiptText size={17} />}</div><div className="transaction-name"><strong>{item.title}</strong><span>{item.category} · {item.person} · {item.date}</span>{item.note && <small>{item.note}</small>}</div><div className={cn("transaction-amount", item.kind === "income" && "income")}>{item.kind === "income" ? "+" : "−"}{exactMoney.format(item.amount)}</div></div>)}</div></section></>;
}

function DebtView({ debts, onSave, onDelete }: { debts: Debt[]; onSave: (item: Debt) => void; onDelete: (id: string) => void }) {
  const total = debts.reduce((sum, item) => sum + item.remaining, 0); const monthly = debts.reduce((sum, item) => sum + item.monthly, 0);
  return <section className="content-page"><div className="view-header"><div><p className="eyebrow">OBLIGAȚII PLANIFICATE</p><h1>Datorii sub <em>control.</em></h1><p className="header-subtitle">Adaugă credite, rate și împrumuturi, apoi modifică sau șterge orice intrare.</p></div><DebtDialog onSave={onSave} trigger={<Button className="quick-add"><Plus size={17} /> Adaugă datorie</Button>} /></div>{debts.length ? <><div className="debt-summary"><section><p>Total rămas</p><strong>{money.format(total)}</strong><span>{debts.length} angajamente active</span></section><section><p>Plăți recurente</p><strong>{money.format(monthly)}</strong><span>Totalul ratelor lunare</span></section><section className="debt-summary-accent"><p>Următorul pas</p><strong>Revizuiește scadențele</strong><span>Actualizează ratele după fiecare plată</span></section></div><div className="debt-list">{debts.map((debt) => <article key={debt.id} className="paper-card debt-item"><div className={cn("debt-marker", debt.tone)} /><div className="debt-title"><strong>{debt.name}</strong><span>Scadență: {debt.due}</span></div><div><p>Rată lunară</p><strong>{money.format(debt.monthly)}</strong></div><div><p>Sold rămas</p><strong>{money.format(debt.remaining)}</strong></div><div className="debt-progress"><div><span>Rată față de sold</span><strong>{debt.remaining ? `${Math.min(100, Math.round((debt.monthly / debt.remaining) * 100))}%` : "Achitat"}</strong></div><BudgetRibbon spent={debt.monthly} budget={Math.max(debt.remaining, debt.monthly)} color={debt.tone === "forest" ? "#143C36" : debt.tone === "honey" ? "#E6B84A" : "#C9674D"} /></div><div className="inline-actions"><DebtDialog debt={debt} onSave={onSave} trigger={<button aria-label={`Modifică ${debt.name}`}><Pencil size={16} /></button>} /><button className="delete-button" aria-label={`Șterge ${debt.name}`} onClick={() => window.confirm(`Ștergi datoria „${debt.name}”?`) && onDelete(debt.id)}><Trash2 size={16} /></button></div></article>)}</div></> : <EmptyState icon={CircleDollarSign} title="Nicio datorie înregistrată" copy="Dacă aveți credit, rate sau bani împrumutați, adaugă-i aici pentru a-i ține sub control." action={<DebtDialog onSave={onSave} trigger={<Button className="outline-action"><Plus size={16} /> Prima datorie</Button>} />} />}</section>;
}

function SavingsView({ savings, onSave, onDelete }: { savings: SavingsGoal[]; onSave: (item: SavingsGoal) => void; onDelete: (id: string) => void }) {
  return <section className="content-page"><div className="view-header"><div><p className="eyebrow">OBIECTIVE COMUNE</p><h1>Economiile au <em>un loc.</em></h1><p className="header-subtitle">Stabilește obiective reale, actualizează progresul și șterge ce nu mai este relevant.</p></div><SavingsDialog onSave={onSave} trigger={<Button className="quick-add"><Plus size={17} /> Obiectiv nou</Button>} /></div>{savings.length ? <div className="goals-grid">{savings.map((goal, index) => <article className={cn("goal-card", index === 0 && "goal-card-featured")} key={goal.id}><div className="goal-card-top"><div className={cn("goal-icon", goal.tone === "coral" && "coral")}><PiggyBank size={19} /></div><div className="inline-actions"><SavingsDialog goal={goal} onSave={onSave} trigger={<button aria-label={`Modifică ${goal.name}`}><Pencil size={16} /></button>} /><button className="delete-button" aria-label={`Șterge ${goal.name}`} onClick={() => window.confirm(`Ștergi obiectivul „${goal.name}”?`) && onDelete(goal.id)}><Trash2 size={16} /></button></div></div><p className="eyebrow">{goal.due}</p><h2>{goal.name}</h2><p className="goal-copy">Ai pus deoparte {money.format(goal.current)}. Mai lipsesc {money.format(Math.max(0, goal.target - goal.current))} până la țintă.</p><BudgetRibbon spent={goal.current} budget={goal.target} color={goal.tone === "forest" ? "#143C36" : goal.tone === "coral" ? "#C9674D" : "#E6B84A"} /><div className="goal-total"><strong>{money.format(goal.current)}</strong><span> din {money.format(goal.target)}</span></div></article>)}</div> : <EmptyState icon={PiggyBank} title="Niciun obiectiv de economisire" copy="Începe cu un fond de siguranță, o vacanță sau orice plan important pentru familie." action={<SavingsDialog onSave={onSave} trigger={<Button className="outline-action"><Plus size={16} /> Creează obiectiv</Button>} />} />}</section>;
}

function MovementsView({ transactions, memberName, onSave, onDelete }: { transactions: Transaction[]; memberName: string; onSave: (item: Transaction) => void; onDelete: (id: string) => void }) {
  const [filter, setFilter] = useState<"all" | TransactionKind>("all"); const listed = filter === "all" ? transactions : transactions.filter((item) => item.kind === filter);
  return <section className="content-page"><div className="view-header"><div><p className="eyebrow">REGISTRU DE FAMILIE</p><h1>Fiecare leu, <em>cu context.</em></h1><p className="header-subtitle">Corectează, modifică sau șterge orice mișcare introdusă greșit.</p></div><TransactionDialog memberName={memberName} onSave={onSave} trigger={<Button className="quick-add"><Plus size={17} /> Adaugă mișcare</Button>} /></div><div className="filter-pills"><button onClick={() => setFilter("all")} className={cn(filter === "all" && "is-selected")}>Toate</button><button onClick={() => setFilter("expense")} className={cn(filter === "expense" && "is-selected")}>Cheltuieli</button><button onClick={() => setFilter("income")} className={cn(filter === "income" && "is-selected")}>Venituri</button></div>{listed.length ? <section className="paper-card ledger-table"><div className="ledger-head"><span>MIȘCARE</span><span>CATEGORIE</span><span>INTRODUS DE</span><span>SUMĂ</span><span /></div>{listed.map((item) => <div className="ledger-row" key={item.id}><div><span className={cn("ledger-icon", item.kind)}>{item.kind === "income" ? <ArrowDownRight size={16} /> : <ArrowUpRight size={16} />}</span><strong>{item.title}</strong><small>{item.date}</small></div><span className="ledger-category">{item.category}</span><span>{item.person}</span><strong className={item.kind === "income" ? "income-value" : "expense-value"}>{item.kind === "income" ? "+" : "−"}{exactMoney.format(item.amount)}</strong><div className="inline-actions"><TransactionDialog transaction={item} memberName={memberName} onSave={onSave} trigger={<button aria-label={`Modifică ${item.title}`}><Pencil size={16} /></button>} /><button className="delete-button" aria-label={`Șterge ${item.title}`} onClick={() => window.confirm(`Ștergi mișcarea „${item.title}”?`) && onDelete(item.id)}><Trash2 size={16} /></button></div></div>)}</section> : <EmptyState icon={WalletCards} title="Nicio mișcare în acest filtru" copy="Poți crea o intrare nouă sau poți alege alt filtru." action={<TransactionDialog memberName={memberName} onSave={onSave} trigger={<Button className="outline-action"><Plus size={16} /> Adaugă mișcare</Button>} />} />}</section>;
}

function WeeklyPlanView({ data, onChange, onGo }: { data: AppData; onChange: (data: AppData) => void; onGo: (view: View) => void }) {
  const plan = data.settings.salaryPlan; const [periodStart, setPeriodStart] = useState(plan.periodStart || new Date().toISOString().slice(0, 10)); const [nextPayday, setNextPayday] = useState(plan.nextPayday); const [sourceIds, setSourceIds] = useState(plan.sourceIds || []); const [totalLimit, setTotalLimit] = useState(plan.totalLimit ? String(plan.totalLimit) : ""); const [weeklyLimit, setWeeklyLimit] = useState(plan.weeklyLimit ? String(plan.weeklyLimit) : ""); const [allocationLabel, setAllocationLabel] = useState(""); const [allocationAmount, setAllocationAmount] = useState(""); const [allocationScope, setAllocationScope] = useState<"member" | "category">("member"); const [allocationTarget, setAllocationTarget] = useState(data.settings.members[0]?.id || "");
  useEffect(() => { setPeriodStart(plan.periodStart || new Date().toISOString().slice(0, 10)); setNextPayday(plan.nextPayday); setSourceIds(plan.sourceIds || []); setTotalLimit(plan.totalLimit ? String(plan.totalLimit) : ""); setWeeklyLimit(plan.weeklyLimit ? String(plan.weeklyLimit) : ""); }, [plan]);
  const selectedSources = data.settings.paymentSources.filter((source) => !sourceIds.length || sourceIds.includes(source.id)); const sourcesBalance = selectedSources.reduce((sum, source) => sum + source.balance, 0); const startDate = new Date(`${periodStart}T12:00:00`); const payDate = nextPayday ? new Date(`${nextPayday}T12:00:00`) : undefined; const validEnd = payDate && payDate.valueOf() >= startDate.valueOf() ? payDate : new Date(startDate.valueOf() + 6 * 86_400_000); const daysRemaining = Math.max(1, Math.floor((validEnd.valueOf() - startDate.valueOf()) / 86_400_000) + 1); const weeksRemaining = Math.max(1, Math.ceil(daysRemaining / 7)); const specifiedLimit = Math.max(0, readNumber(totalLimit)); const planLimit = specifiedLimit || sourcesBalance; const derivedWeekly = planLimit ? planLimit / weeksRemaining : 0; const effectiveWeekly = Math.max(0, readNumber(weeklyLimit)) || derivedWeekly; const allocated = plan.allocations.reduce((sum, item) => sum + item.amount, 0); const remainingToAllocate = planLimit - allocated; const calendarWeeks = Array.from({ length: weeksRemaining }, (_, index) => { const start = new Date(startDate.valueOf() + index * 7 * 86_400_000); const end = new Date(Math.min(validEnd.valueOf(), start.valueOf() + 6 * 86_400_000)); const amount = index === weeksRemaining - 1 ? Math.max(0, planLimit - effectiveWeekly * index) : Math.min(effectiveWeekly, Math.max(0, planLimit - effectiveWeekly * index)); return { index, start, end, amount }; });
  const savePlan = () => onChange({ ...data, settings: { ...data.settings, salaryPlan: { ...plan, periodStart, nextPayday, sourceIds, totalLimit: planLimit, weeklyLimit: Math.max(0, readNumber(weeklyLimit)) } } });
  const addAllocation = () => { const amount = readNumber(allocationAmount); const targetName = allocationScope === "member" ? data.settings.members.find((item) => item.id === allocationTarget)?.name : allocationTarget; const label = allocationLabel.trim() || targetName; if (!label || !Number.isFinite(amount) || amount <= 0) return; onChange({ ...data, settings: { ...data.settings, salaryPlan: { ...plan, allocations: [...plan.allocations, { id: newId("allocation"), label, amount, memberId: allocationScope === "member" ? allocationTarget : undefined, category: allocationScope === "category" ? allocationTarget : undefined }] } } }); setAllocationLabel(""); setAllocationAmount(""); };
  const targets = allocationScope === "member" ? data.settings.members.map((item) => ({ value: item.id, label: item.name })) : [...expenseCategories, ...data.settings.customCategories].map((item) => ({ value: item, label: item }));
  return <section className="content-page plan-editor-page"><div className="view-header"><div><p className="eyebrow">PLAN CALENDARISTIC PÂNĂ LA SALARIU</p><h1>Împarte banii <em>înainte să se ducă.</em></h1><p className="header-subtitle">Alege intervalul, selectează banii disponibili pe carduri sau cash și repartizează-i săptămânal, pe membri sau categorii.</p></div><Button className="quick-add" onClick={savePlan}><Check size={16} /> Salvează planul</Button></div><div className="plan-editor-grid"><section className="week-allowance"><p className="eyebrow text-[#DDEAE4]">LIMITĂ PENTRU URMĂTOAREA SĂPTĂMÂNĂ</p><strong>{money.format(effectiveWeekly)}</strong><p>{daysRemaining} zile în interval · {weeksRemaining} săptămâni calendaristice de acoperit.</p><div className="plan-calculation"><span>Din surse selectate: <b>{money.format(sourcesBalance)}</b></span><span>Limită totală: <b>{money.format(planLimit)}</b></span><span>Alocat: <b>{money.format(allocated)}</b></span><span>Nealocat: <b>{money.format(remainingToAllocate)}</b></span></div><button onClick={() => onGo("Mișcări")}>Vezi cheltuielile <ChevronRight size={15} /></button></section><section className="paper-card plan-inputs"><div className="section-heading"><div><p className="eyebrow">PERIOADĂ ȘI BANI DISPONIBILI</p><h2>Setează cadrul</h2></div><Goal size={20} /></div><div className="dialog-grid"><label className="field-label">Începe la<input type="date" value={periodStart} onChange={(event) => setPeriodStart(event.target.value)} /></label><label className="field-label">Până la următorul salariu<input type="date" min={periodStart} value={nextPayday} onChange={(event) => setNextPayday(event.target.value)} /></label></div><div className="budget-source-picker"><p className="field-label">Folosește banii din</p>{data.settings.paymentSources.map((source) => <label key={source.id} className={cn("source-budget-option", (!sourceIds.length || sourceIds.includes(source.id)) && "is-selected")}><input type="checkbox" checked={!sourceIds.length || sourceIds.includes(source.id)} onChange={() => setSourceIds((current) => { const all = data.settings.paymentSources.map((item) => item.id); const active = current.length ? current : all; const next = active.includes(source.id) ? active.filter((id) => id !== source.id) : [...active, source.id]; return next.length === all.length ? [] : next; })} /><span><strong>{source.name}</strong><small>{data.settings.members.find((member) => member.id === source.memberId)?.name || "comun"}</small></span><b>{money.format(source.balance)}</b></label>)}</div><label className="field-label">Buget total alocat pentru perioadă<Input inputMode="decimal" value={totalLimit} onChange={(event) => setTotalLimit(event.target.value)} placeholder={sourcesBalance ? `implicit ${money.format(sourcesBalance)}` : "ex. 600"} /></label><label className="field-label">Limită pe săptămână <Input inputMode="decimal" value={weeklyLimit} onChange={(event) => setWeeklyLimit(event.target.value)} placeholder={derivedWeekly ? exactMoney.format(derivedWeekly) : "se calculează din buget"} /></label><p className="settings-note">Dacă nu introduci o limită totală, se folosește soldul surselor bifate. Dacă lași limita săptămânală goală, perioada este împărțită automat pe săptămâni.</p></section><section className="paper-card calendar-allocation"><div className="section-heading"><div><p className="eyebrow">CALENDARUL BANILOR</p><h2>Limita pentru fiecare săptămână</h2></div><span className="hand-note">automat</span></div><div className="calendar-weeks">{calendarWeeks.map((week) => <div key={week.index} className="calendar-week"><span>Săpt. {week.index + 1}</span><small>{week.start.toLocaleDateString("ro-RO", { day: "2-digit", month: "short" })} – {week.end.toLocaleDateString("ro-RO", { day: "2-digit", month: "short" })}</small><BudgetRibbon spent={0} budget={Math.max(week.amount, 1)} color="#E6B84A" /><strong>{money.format(week.amount)}</strong></div>)}</div></section><section className="paper-card allocation-board plan-allocations"><div className="section-heading"><div><p className="eyebrow">REPARTIZARE EXPLICITĂ</p><h2>Eu, soția sau o categorie</h2></div><span className="hand-note">editabil</span></div><div className="allocation-form"><select value={allocationScope} onChange={(event) => { const scope = event.target.value as "member" | "category"; setAllocationScope(scope); setAllocationTarget(scope === "member" ? data.settings.members[0]?.id || "" : expenseCategories[0]); }}><option value="member">Membru</option><option value="category">Categorie</option></select><select value={allocationTarget} onChange={(event) => setAllocationTarget(event.target.value)}>{targets.map((target) => <option key={target.value} value={target.value}>{target.label}</option>)}</select><Input value={allocationLabel} onChange={(event) => setAllocationLabel(event.target.value)} placeholder="Nume opțional" /><Input value={allocationAmount} onChange={(event) => setAllocationAmount(event.target.value)} inputMode="decimal" placeholder="lei" /><Button onClick={addAllocation}><Plus size={15} /> Adaugă</Button></div>{plan.allocations.length ? <div className="allocation-list">{plan.allocations.map((item) => <div className="allocation-row plan-allocation-row" key={item.id}><span>{item.label}</span><BudgetRibbon spent={item.amount} budget={Math.max(planLimit, item.amount)} color={item.category ? categoryColors[item.category] || "#E6B84A" : "#143C36"} /><strong>{money.format(item.amount)}</strong><button className="delete-button allocation-delete" aria-label={`Șterge alocarea ${item.label}`} onClick={() => onChange({ ...data, settings: { ...data.settings, salaryPlan: { ...plan, allocations: plan.allocations.filter((entry) => entry.id !== item.id) } } })}><Trash2 size={15} /></button></div>)}</div> : <p className="empty-copy">Exemplu: selectează cardul tău și cash-ul soției, apoi repartizează „Eu — 300 lei”, „Soția — 300 lei” sau categoria „Taxi”.</p>}</section></div></section>;
}

function ReceiptDialog({ trigger, receipt, onSave }: { trigger: ReactElement; receipt?: Receipt; onSave: (item: Receipt) => void }) {
  const [open, setOpen] = useState(false); const [vendor, setVendor] = useState(receipt?.vendor ?? ""); const [amount, setAmount] = useState(receipt ? String(receipt.amount) : ""); const [category, setCategory] = useState(receipt?.category ?? "Alimente"); const [note, setNote] = useState(receipt?.note ?? ""); const [imageData, setImageData] = useState(receipt?.imageData);
  useEffect(() => { if (open) { setVendor(receipt?.vendor ?? ""); setAmount(receipt ? String(receipt.amount) : ""); setCategory(receipt?.category ?? "Alimente"); setNote(receipt?.note ?? ""); setImageData(receipt?.imageData); } }, [open, receipt]);
  const loadImage = (file?: File) => { if (!file) return; if (file.size > 1_500_000) { window.alert("Imaginea este prea mare pentru stocarea locală. Alege un fișier de maximum 1,5 MB."); return; } const reader = new FileReader(); reader.onload = () => setImageData(String(reader.result)); reader.readAsDataURL(file); };
  const submit = () => { const numeric = readNumber(amount); if (!vendor.trim() || !Number.isFinite(numeric) || numeric <= 0) return; onSave({ id: receipt?.id ?? newId("receipt"), vendor: vendor.trim(), amount: numeric, category, date: receipt?.date || todayLabel(), note: note.trim() || undefined, imageData }); setOpen(false); };
  return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild>{trigger}</DialogTrigger><DialogContent className="add-dialog"><DialogHeader><DialogTitle>{receipt ? "Modifică bonul" : "Adaugă bon"}</DialogTitle></DialogHeader><label className="field-label">Magazin / furnizor<Input value={vendor} onChange={(event) => setVendor(event.target.value)} placeholder="ex. Lidl" autoFocus /></label><div className="dialog-grid"><label className="field-label">Total bon (lei)<Input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" /></label><label className="field-label">Categorie<select value={category} onChange={(event) => setCategory(event.target.value)}>{expenseCategories.map((item) => <option key={item}>{item}</option>)}</select></label></div><label className="field-label">Poză bon (opțional, max. 1,5 MB)<input type="file" accept="image/*" onChange={(event) => loadImage(event.target.files?.[0])} /></label>{imageData && <img className="receipt-preview" src={imageData} alt="Previzualizare bon" />}<label className="field-label">Notiță / produse<Textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="ex. apă, alimente, produse de curățenie" /></label><Button onClick={submit} className="save-transaction"><Check size={16} /> Salvează bonul</Button></DialogContent></Dialog>;
}

function ReceiptsView({ receipts, onSave, onDelete }: { receipts: Receipt[]; onSave: (item: Receipt) => void; onDelete: (id: string) => void }) { return <section className="content-page"><div className="view-header"><div><p className="eyebrow">BONURI ȘI PRODUSE</p><h1>Vezi ce ai <em>cumpărat.</em></h1><p className="header-subtitle">Adaugă bonul manual sau atașează o fotografie mică; valoarea lui intră automat în cheltuieli.</p></div><ReceiptDialog onSave={onSave} trigger={<Button className="quick-add"><Camera size={17} /> Adaugă bon</Button>} /></div>{receipts.length ? <section className="receipt-register">{receipts.map((receipt) => <article className="paper-card receipt-entry" key={receipt.id}>{receipt.imageData ? <img src={receipt.imageData} alt={`Bon ${receipt.vendor}`} /> : <div className="receipt-placeholder"><ReceiptText size={26} /></div>}<div><p className="eyebrow">{receipt.date} · {receipt.category}</p><h2>{receipt.vendor}</h2><strong>{exactMoney.format(receipt.amount)}</strong>{receipt.note && <p>{receipt.note}</p>}</div><div className="inline-actions"><ReceiptDialog receipt={receipt} onSave={onSave} trigger={<button aria-label={`Modifică bonul ${receipt.vendor}`}><Pencil size={16} /></button>} /><button className="delete-button" aria-label={`Șterge bonul ${receipt.vendor}`} onClick={() => window.confirm(`Ștergi bonul „${receipt.vendor}”? Cheltuiala asociată va fi ștearsă.`) && onDelete(receipt.id)}><Trash2 size={16} /></button></div></article>)}</section> : <EmptyState icon={ReceiptText} title="Niciun bon înregistrat" copy="Înregistrează un bon pentru a crea automat o cheltuială în categoria aleasă. Poza este opțională și rămâne doar în browser." action={<ReceiptDialog onSave={onSave} trigger={<Button className="outline-action"><Camera size={16} /> Adaugă primul bon</Button>} />} />}</section>; }

function AssistantView({ data }: { data: AppData }) { const [presetQuestion, setPresetQuestion] = useState(""); const prompts = ["Unde am cheltuit cel mai mult?", "Ce datorii trebuie revizuite?", "Care este limita până la salariu?", "Ce obiective de economisire sunt active?"]; return <section className="content-page"><div className="view-header"><div><p className="eyebrow">GHID DE FAMILIE</p><h1>Întrebări bune. <em>Date clare.</em></h1><p className="header-subtitle">Asistentul explică situația de pe acest dispozitiv, fără a trimite date financiare în altă parte.</p></div></div><div className="assistant-page"><AssistantCard data={data} presetQuestion={presetQuestion} /><section className="paper-card suggestion-board"><p className="eyebrow">ÎNTREBĂRI UTILE</p><h2>Pornește de aici</h2>{prompts.map((item) => <button key={item} onClick={() => setPresetQuestion(`${item} ${Date.now()}`)}>{item}<ChevronRight size={16} /></button>)}</section></div></section>; }

function SyncView({ data, onChange }: { data: AppData; onChange: (data: AppData) => void }) {
  const [token, setToken] = useState(""); const [secret, setSecret] = useState(""); const [busy, setBusy] = useState<"push" | "pull" | null>(null); const [message, setMessage] = useState(""); const [lastSha, setLastSha] = useState<string | undefined>();
  const owner = "Balty1991"; const repo = "buget-familie-date"; const path = "family-sync.enc.json";
  const validate = () => { if (!token.trim()) throw new Error("Introdu un token GitHub cu acces Contents: Read and write numai la repo-ul privat de date."); if (secret.trim().length < 12) throw new Error("Alege o parolă de familie de minimum 12 caractere; ea criptează datele înainte de sincronizare."); };
  const download = async () => { try { validate(); setBusy("pull"); setMessage(""); const remote = await getRemotePackage({ token: token.trim(), owner, repo, path }); if (!remote) { setMessage("Nu există încă o copie sincronizată. Încarcă prima copie de pe acest dispozitiv."); return; } const restored = await decryptFamilyData(remote.envelope, secret); if (!window.confirm(`Înlocuiești datele locale cu copia criptată din ${new Date(remote.envelope.createdAt).toLocaleString("ro-RO")}?`)) return; onChange(restored); setLastSha(remote.sha); setMessage(`Copie descărcată și decriptată. Ultima actualizare: ${new Date(remote.envelope.createdAt).toLocaleString("ro-RO")}.`); } catch (error) { setMessage(error instanceof Error ? error.message : "Nu s-a putut descărca pachetul."); } finally { setBusy(null); } };
  const upload = async () => { try { validate(); setBusy("push"); setMessage(""); const remote = await getRemotePackage({ token: token.trim(), owner, repo, path }); if (remote && remote.sha !== lastSha && !window.confirm("Există o copie mai nouă sau necunoscută în repo-ul privat. Dacă încarci acum, o vei suprascrie. Continui?")) return; const envelope = await encryptFamilyData(data, secret); const sha = await saveRemotePackage({ token: token.trim(), owner, repo, path, envelope, sha: remote?.sha }); setLastSha(sha); setMessage(`Copie criptată încărcată. GitHub nu a primit tokenul după finalizarea cererii.`); } catch (error) { setMessage(error instanceof Error ? error.message : "Nu s-a putut încărca pachetul."); } finally { setBusy(null); } };
  return <section className="content-page sync-page"><div className="view-header"><div><p className="eyebrow">SINCRONIZARE PRIVATĂ</p><h1>Date comune, <em>închise.</em></h1><p className="header-subtitle">Aplicația rămâne publică pe GitHub Pages; numai pachetul financiar criptat ajunge în repo-ul privat al familiei.</p></div></div><div className="sync-layout"><section className="sync-hero"><div className="sync-orbit"><Cloud size={21} /></div><p className="eyebrow text-[#DDEAE4]">REPO PRIVAT CONECTAT</p><h2>{owner}/{repo}</h2><p>Pe GitHub se salvează doar un fișier criptat AES-GCM. Parola de familie nu este stocată în aplicație sau repo.</p><div className="sync-status"><span className="live-dot" /> Sincronizare manuală, sub controlul vostru</div></section><section className="paper-card sync-config"><div className="section-heading"><div><p className="eyebrow">ACCESUL DISPOZITIVULUI</p><h2>Conectează în siguranță</h2></div><Settings size={19} /></div><label className="field-label">Token GitHub limitat<input type="password" autoComplete="off" value={token} onChange={(event) => setToken(event.target.value)} placeholder="github_pat_..." /></label><label className="field-label">Parola de criptare a familiei<input type="password" autoComplete="new-password" value={secret} onChange={(event) => setSecret(event.target.value)} placeholder="minimum 12 caractere" /></label><p className="settings-note">Tokenul rămâne numai în memoria acestei pagini. Creează un token fine-grained cu **Contents: Read and write**, limitat la repo-ul privat <strong>{repo}</strong>.</p></section><section className="paper-card sync-actions-card"><div className="section-heading"><div><p className="eyebrow">COPIA DE SIGURANȚĂ</p><h2>Alege direcția</h2></div><Cloud size={19} /></div><p>Mai întâi descarcă dacă ai lucrat pe alt telefon. Încarcă numai după ce verifici că datele locale sunt cele pe care vrei să le păstrezi.</p><div className="sync-actions"><Button className="quick-add" disabled={busy !== null} onClick={download}><Download size={16} /> {busy === "pull" ? "Se descarcă…" : "Descarcă din repo"}</Button><Button className="save-transaction" disabled={busy !== null} onClick={upload}><Cloud size={16} /> {busy === "push" ? "Se criptează…" : "Criptează și încarcă"}</Button></div></section><section className="paper-card sync-guide"><p className="eyebrow">PE AL DOILEA DISPOZITIV</p><ol><li>Deschide aceeași aplicație publică.</li><li>Intră la Sincronizare și folosește un token limitat al acelui utilizator GitHub.</li><li>Introdu exact aceeași parolă de criptare a familiei.</li><li>Apasă „Descarcă din repo”.</li></ol></section></div>{message && <div className="settings-message sync-message" role="status"><Check size={16} /> {message}</div>}</section>;
}

function FamilyControlPanel({ data, onChange }: { data: AppData; onChange: (data: AppData) => void }) {
  const [newMember, setNewMember] = useState(""); const [newSource, setNewSource] = useState(""); const [sourceKind, setSourceKind] = useState<"card" | "cash" | "meal" | "transfer">("card"); const [sourceMember, setSourceMember] = useState(data.settings.members[0]?.id || ""); const [newCategory, setNewCategory] = useState("");
  const change = (settings: AppData["settings"]) => onChange({ ...data, settings });
  const addMember = () => { const name = newMember.trim(); if (!name || data.settings.members.some((item) => item.name.toLowerCase() === name.toLowerCase())) return; const member = { id: newId("member"), name }; change({ ...data.settings, members: [...data.settings.members, member] }); setSourceMember(member.id); setNewMember(""); };
  const deleteMember = (id: string) => { if (data.settings.members.length === 1 || !window.confirm("Ștergi acest membru? Sursele lui de plată vor rămâne fără proprietar.")) return; change({ ...data.settings, members: data.settings.members.filter((item) => item.id !== id), paymentSources: data.settings.paymentSources.map((item) => item.memberId === id ? { ...item, memberId: undefined } : item) }); };
  const addSource = () => { const name = newSource.trim(); if (!name) return; change({ ...data.settings, paymentSources: [...data.settings.paymentSources, { id: newId("source"), name, kind: sourceKind, memberId: sourceKind === "transfer" ? undefined : sourceMember || undefined, balance: 0 }] }); setNewSource(""); };
  const updateSourceBalance = (id: string, value: string) => { const balance = Math.max(0, readNumber(value) || 0); change({ ...data.settings, paymentSources: data.settings.paymentSources.map((item) => item.id === id ? { ...item, balance } : item) }); };
  const addCategory = () => { const name = newCategory.trim(); if (!name || expenseCategories.includes(name) || data.settings.customCategories.includes(name)) return; change({ ...data.settings, customCategories: [...data.settings.customCategories, name] }); setNewCategory(""); };
  return <section className="paper-card family-controls"><div className="section-heading"><div><p className="eyebrow">ECHIPA ȘI INSTRUMENTELE</p><h2>Cine plătește și din ce</h2></div><UsersRound size={19} /></div><p className="settings-note">Membrii, sursele, soldurile și categoriile apar imediat în formularul fiecărei mișcări și în planul calendaristic.</p><div className="control-group"><strong>Membrii familiei</strong><div className="chip-list">{data.settings.members.map((member) => <span key={member.id} className="control-chip">{member.name}<button aria-label={`Șterge ${member.name}`} onClick={() => deleteMember(member.id)}><X size={12} /></button></span>)}</div><div className="inline-add"><Input value={newMember} onChange={(event) => setNewMember(event.target.value)} placeholder="ex. Soția" onKeyDown={(event) => event.key === "Enter" && addMember()} /><Button type="button" onClick={addMember}>Adaugă</Button></div></div><div className="control-group"><strong>Surse de plată și sold disponibil</strong><div className="source-balance-list">{data.settings.paymentSources.map((source) => <div key={source.id} className="source-balance-row"><span><b>{source.name}</b><small>{data.settings.members.find((member) => member.id === source.memberId)?.name || "comun"}</small></span><label>Sold (lei)<Input inputMode="decimal" aria-label={`Sold pentru ${source.name}`} value={String(source.balance)} onChange={(event) => updateSourceBalance(source.id, event.target.value)} /></label><button aria-label={`Șterge ${source.name}`} onClick={() => change({ ...data.settings, paymentSources: data.settings.paymentSources.filter((item) => item.id !== source.id) })}><X size={14} /></button></div>)}</div><div className="source-add"><Input value={newSource} onChange={(event) => setNewSource(event.target.value)} placeholder="ex. Card soție" /><select value={sourceKind} onChange={(event) => setSourceKind(event.target.value as typeof sourceKind)}><option value="card">Card</option><option value="cash">Cash</option><option value="meal">Bonuri masă</option><option value="transfer">Transfer</option></select><select value={sourceMember} onChange={(event) => setSourceMember(event.target.value)} disabled={sourceKind === "transfer"}>{data.settings.members.map((member) => <option key={member.id} value={member.id}>{member.name}</option>)}</select><Button type="button" onClick={addSource}>Adaugă</Button></div></div><div className="control-group"><strong>Categorii personalizate</strong><div className="chip-list">{data.settings.customCategories.map((category) => <span key={category} className="control-chip">{category}<button aria-label={`Șterge categoria ${category}`} onClick={() => change({ ...data.settings, customCategories: data.settings.customCategories.filter((item) => item !== category) })}><X size={12} /></button></span>)}</div><div className="inline-add"><Input value={newCategory} onChange={(event) => setNewCategory(event.target.value)} placeholder="ex. Taxi" onKeyDown={(event) => event.key === "Enter" && addCategory()} /><Button type="button" onClick={addCategory}>Adaugă</Button></div></div></section>;
}

function SettingsView({ data, onChange, onReset }: { data: AppData; onChange: (data: AppData) => void; onReset: () => void }) {
  const { theme, toggleTheme } = useTheme(); const inputRef = useRef<HTMLInputElement>(null); const [familyName, setFamilyName] = useState(data.settings.familyName); const [memberName, setMemberName] = useState(data.settings.memberName); const [familyCode, setFamilyCode] = useState(data.settings.familyCode); const [importCode, setImportCode] = useState(""); const [message, setMessage] = useState("");
  useEffect(() => { setFamilyName(data.settings.familyName); setMemberName(data.settings.memberName); setFamilyCode(data.settings.familyCode); }, [data.settings]);
  const saveSettings = () => { onChange({ ...data, settings: { ...data.settings, familyName: familyName.trim() || "Familia mea", memberName: memberName.trim() || "Eu", familyCode: familyCode.trim().toUpperCase() || createFamilyCode() } }); setMessage("Setările familiei au fost salvate pe acest dispozitiv."); };
  const exportData = () => { const packageData = { format: "Buget Familie", version: 1, exportedAt: new Date().toISOString(), familyCode: data.settings.familyCode, data }; const blob = new Blob([JSON.stringify(packageData, null, 2)], { type: "application/json" }); const link = document.createElement("a"); link.href = URL.createObjectURL(blob); link.download = `buget-familie-${data.settings.familyCode.toLowerCase()}.json`; link.click(); URL.revokeObjectURL(link.href); setMessage("Pachetul a fost descărcat. Trimite-l manual pe celălalt dispozitiv."); };
  const importData = (file?: File) => { if (!file) return; const reader = new FileReader(); reader.onload = () => { try { const parsed = JSON.parse(String(reader.result)); if (parsed?.format !== "Buget Familie" || !parsed?.data || !parsed?.familyCode) throw new Error("format"); if (importCode.trim().toUpperCase() !== String(parsed.familyCode).toUpperCase()) { setMessage("Codul de familie nu corespunde pachetului ales."); return; } onChange(parsed.data as AppData); setMessage("Datele au fost importate pe acest dispozitiv."); } catch { setMessage("Pachetul ales nu este valid."); } }; reader.readAsText(file); };
  return <section className="content-page settings-page"><div className="view-header"><div><p className="eyebrow">CONTROLUL SPAȚIULUI</p><h1>Setări de <em>familie.</em></h1><p className="header-subtitle">Aici controlezi identitatea, membrii, sursele de plată, tema, resetarea și transferul manual.</p></div></div><div className="settings-layout"><section className="paper-card settings-panel"><div className="section-heading"><div><p className="eyebrow">IDENTITATE</p><h2>Spațiul vostru local</h2></div><UsersRound size={19} /></div><label className="field-label">Numele familiei<Input value={familyName} onChange={(event) => setFamilyName(event.target.value)} placeholder="ex. Casa Popescu" /></label><label className="field-label">Numele tău<Input value={memberName} onChange={(event) => setMemberName(event.target.value)} placeholder="ex. Andrei" /></label><label className="field-label">Cod de familie<Input value={familyCode} onChange={(event) => setFamilyCode(event.target.value.toUpperCase())} maxLength={12} /></label><div className="settings-actions"><Button className="save-transaction" onClick={saveSettings}><Check size={16} /> Salvează setările</Button><button className="text-button" onClick={() => setFamilyCode(createFamilyCode())}>Cod nou <RotateCcw size={15} /></button></div></section><section className="paper-card settings-panel"><div className="section-heading"><div><p className="eyebrow">ASPECT</p><h2>Lucrează confortabil</h2></div>{theme === "dark" ? <Moon size={19} /> : <Sun size={19} />}</div><div className="setting-row"><div><strong>Temă întunecată</strong><p>Reduce lumina puternică atunci când înregistrați seara.</p></div><button className={cn("theme-toggle", theme === "dark" && "is-dark")} onClick={toggleTheme} aria-label="Schimbă tema"><span>{theme === "dark" ? <Moon size={14} /> : <Sun size={14} />}</span></button></div><p className="settings-note">Preferința de temă se salvează separat pe fiecare dispozitiv.</p></section><FamilyControlPanel data={data} onChange={onChange} /><section className="paper-card transfer-card"><div className="section-heading"><div><p className="eyebrow">MUTĂ DATELE</p><h2>Transfer manual între dispozitive</h2></div><Download size={19} /></div><p>GitHub Pages nu oferă sincronizare automată. Exportă pachetul, trimite-l personal și importă-l cu același cod de familie.</p><div className="transfer-steps"><span>1. Exportă</span><ChevronRight size={14} /><span>2. Trimite fișierul</span><ChevronRight size={14} /><span>3. Importă</span></div><div className="transfer-actions"><Button className="quick-add" onClick={exportData}><Download size={16} /> Exportă pachetul</Button><label className="file-button"><FileUp size={16} /> Importă pachetul<input ref={inputRef} type="file" accept="application/json" onChange={(event) => importData(event.target.files?.[0])} /></label></div><label className="field-label import-code">Codul pachetului pe care îl imporți<Input value={importCode} onChange={(event) => setImportCode(event.target.value.toUpperCase())} placeholder="ex. AB12CD" maxLength={12} /></label></section><section className="paper-card settings-panel danger-panel"><div className="section-heading"><div><p className="eyebrow">RESETARE</p><h2>Începe de la zero</h2></div><RotateCcw size={19} /></div><p>Șterge toate mișcările, datoriile, economiile, bonurile și planurile locale doar de pe acest dispozitiv. Această acțiune nu poate fi anulată.</p><Button variant="outline" className="reset-button" onClick={() => window.confirm("Ștergi toate datele locale ale familiei de pe acest dispozitiv?") && onReset()}><Trash2 size={16} /> Resetează datele locale</Button></section></div>{message && <div className="settings-message"><Check size={16} /> {message}</div>}</section>;
}

export default function Home() {
  const [activeView, setActiveView] = useState<View>("Panou");
  const [data, setData] = useState<AppData>(() => { try { const stored = window.localStorage.getItem(STORE_KEY); if (!stored) return createEmptyAppData(); const parsed = JSON.parse(stored) as Omit<Partial<AppData>, "version"> & { version?: number }; if ((parsed?.version === 3 || parsed?.version === 4 || parsed?.version === 5) && Array.isArray(parsed.transactions) && Array.isArray(parsed.debts) && Array.isArray(parsed.savings) && parsed.settings) { const legacy = parsed.settings as Partial<AppData["settings"]>; const memberName = legacy.memberName || "Eu"; const members = legacy.members?.length ? legacy.members : [{ id: "member-me", name: memberName }]; const paymentSources = legacy.paymentSources?.length ? legacy.paymentSources.map((item) => ({ ...item, balance: item.balance || 0 })) : [{ id: "source-debit", name: "Card debit", kind: "card" as const, memberId: members[0].id, balance: 0 }, { id: "source-cash", name: "Cash", kind: "cash" as const, memberId: members[0].id, balance: 0 }, { id: "source-meal", name: "Bonuri de masă", kind: "meal" as const, memberId: members[0].id, balance: 0 }, { id: "source-transfer", name: "Transfer", kind: "transfer" as const, balance: 0 }]; const oldPlan = legacy.salaryPlan; return { ...parsed, version: 5, receipts: Array.isArray(parsed.receipts) ? parsed.receipts : [], settings: { familyName: legacy.familyName || "Familia mea", memberName, familyCode: legacy.familyCode || createFamilyCode(), members, paymentSources, customCategories: legacy.customCategories || [], salaryPlan: { periodStart: oldPlan?.periodStart || new Date().toISOString().slice(0, 10), nextPayday: oldPlan?.nextPayday || "", sourceIds: oldPlan?.sourceIds || [], totalLimit: oldPlan?.totalLimit || 0, weeklyLimit: oldPlan?.weeklyLimit || 0, allocations: oldPlan?.allocations || [] } } } as AppData; } return createEmptyAppData(); } catch { return createEmptyAppData(); } });
  useEffect(() => { window.localStorage.setItem(STORE_KEY, JSON.stringify(data)); }, [data]);
  const update = (fn: (current: AppData) => AppData) => setData((current) => fn(current));
  const saveTransaction = (item: Transaction) => update((current) => { const receiptId = item.id.startsWith("receipt-tx-") ? item.id.replace("receipt-tx-", "") : undefined; return { ...current, transactions: current.transactions.some((entry) => entry.id === item.id) ? current.transactions.map((entry) => entry.id === item.id ? item : entry) : [item, ...current.transactions], receipts: receiptId ? current.receipts.map((receipt) => receipt.id === receiptId ? { ...receipt, vendor: item.title.replace(/^Bon —\s*/, "") || receipt.vendor, amount: item.amount, category: item.category, date: item.date, note: item.note } : receipt) : current.receipts }; });
  const saveDebt = (item: Debt) => update((current) => ({ ...current, debts: current.debts.some((entry) => entry.id === item.id) ? current.debts.map((entry) => entry.id === item.id ? item : entry) : [item, ...current.debts] }));
  const saveSavings = (item: SavingsGoal) => update((current) => ({ ...current, savings: current.savings.some((entry) => entry.id === item.id) ? current.savings.map((entry) => entry.id === item.id ? item : entry) : [item, ...current.savings] }));
  const saveReceipt = (item: Receipt) => update((current) => { const receiptTransaction: Transaction = { id: `receipt-tx-${item.id}`, title: `Bon — ${item.vendor}`, amount: item.amount, kind: "expense", category: item.category, source: "Bon", person: current.settings.memberName || "Eu", date: item.date, note: item.note }; return { ...current, receipts: current.receipts.some((entry) => entry.id === item.id) ? current.receipts.map((entry) => entry.id === item.id ? item : entry) : [item, ...current.receipts], transactions: [receiptTransaction, ...current.transactions.filter((entry) => entry.id !== receiptTransaction.id)] }; });
  const deleteReceipt = (id: string) => update((current) => ({ ...current, receipts: current.receipts.filter((item) => item.id !== id), transactions: current.transactions.filter((item) => item.id !== `receipt-tx-${id}`) }));
  const deleteTransaction = (id: string) => update((current) => { const receiptId = id.startsWith("receipt-tx-") ? id.replace("receipt-tx-", "") : undefined; return { ...current, transactions: current.transactions.filter((item) => item.id !== id), receipts: receiptId ? current.receipts.filter((receipt) => receipt.id !== receiptId) : current.receipts }; });
  const current = () => { if (activeView === "Mișcări") return <MovementsView transactions={data.transactions} memberName={data.settings.memberName} onSave={saveTransaction} onDelete={deleteTransaction} />; if (activeView === "Plan săptămânal") return <WeeklyPlanView data={data} onChange={setData} onGo={setActiveView} />; if (activeView === "Datorii") return <DebtView debts={data.debts} onSave={saveDebt} onDelete={(id) => update((current) => ({ ...current, debts: current.debts.filter((item) => item.id !== id) }))} />; if (activeView === "Economii") return <SavingsView savings={data.savings} onSave={saveSavings} onDelete={(id) => update((current) => ({ ...current, savings: current.savings.filter((item) => item.id !== id) }))} />; if (activeView === "Bonuri") return <ReceiptsView receipts={data.receipts} onSave={saveReceipt} onDelete={deleteReceipt} />; if (activeView === "Asistent") return <AssistantView data={data} />; if (activeView === "Sincronizare") return <SyncView data={data} onChange={setData} />; if (activeView === "Setări") return <SettingsView data={data} onChange={setData} onReset={() => { setData(createEmptyAppData()); setActiveView("Panou"); }} />; return <Dashboard data={data} onAdd={saveTransaction} onGo={setActiveView} />; };
  return <div className="app-shell"><aside className="sidebar"><div className="brand"><div className="brand-mark" aria-label="Monogram B F"><span aria-hidden="true">B/F</span></div><div><strong>Buget</strong><span>Familie</span></div></div><button className="family-switcher" onClick={() => setActiveView("Setări")}><div className="family-avatars"><span>{data.settings.familyName.slice(0, 1).toUpperCase()}</span><span>{data.settings.memberName.slice(0, 1).toUpperCase()}</span></div><div><strong>{data.settings.familyName}</strong><small>spațiu local</small></div><ChevronRight size={15} /></button><nav className="sidebar-nav" aria-label="Navigație principală">{navigation.map(({ label, icon: Icon }) => <button key={label} onClick={() => setActiveView(label)} className={cn(activeView === label && "active")}><Icon size={18} /><span>{label}</span>{label === "Asistent" && <Sparkles className="nav-sparkle" size={14} />}</button>)}</nav><div className="sidebar-footer"><button onClick={() => setActiveView("Setări")} className={cn(activeView === "Setări" && "active")}><Settings size={17} /> Setări</button><div className="privacy-note"><span className="privacy-lock">⌁</span><p><strong>Date locale, sub control.</strong><br />Sincronizare criptată sau export manual.</p></div></div></aside><main className="main-workspace">{current()}</main><div className="mobile-nav">{navigation.slice(0, 5).map(({ label, icon: Icon }) => <button key={label} onClick={() => setActiveView(label)} className={cn(activeView === label && "active")}><Icon size={18} /><span>{label.split(" ")[0]}</span></button>)}</div></div>;
}
